/bin/bash -lc "python3 -c \"
import numpy as np
from scipy import ndimage
d = np.load('source_pixels.npz')
rgb = d['rgb'].astype(int)
# overall motion: pixels that ever change, segmented by time ranges
def moving_bbox(t0, t1):
    diff = np.abs(rgb[t1]-rgb[t0]).sum(axis=2)
    m = diff>30
    lab,n = ndimage.label(m)
    out=[]
    for i in range(1,n+1):
        ys,xs=np.where(lab==i)
        if len(ys)>=8:
            out.append((len(ys),xs.min(),xs.max(),ys.min(),ys.max()))
    return sorted(out,reverse=True)
print('changes 0->30 (pre-collision):')
for c in moving_bbox(0,30): print(' ',c)
print('changes 30->40 (collision):')
for c in moving_bbox(30,40): print(' ',c)
print('changes 40->95 (post):')
for c in moving_bbox(40,95): print(' ',c)
\""
